import type { Response } from 'express';
import Transaction from '../models/transaction.model.js';
import type { AuthRequest } from '../middleware/authmiddleware.js';
import { transactionSchema } from '../validators/transaction.validator.js';


export const createTransaction = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const parsedData = transactionSchema.parse(req.body);

    const newTransaction = new Transaction({
      ...parsedData,
      userId: req.user?.id
    });

    await newTransaction.save();

    res.status(201).json(newTransaction);
  } catch (error: any) {
    res.status(400).json({ message: 'Validation error or server error', error: error.message });
  }
};

export const getTransactions = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const transactions = await Transaction.find({ userId: req.user?.id }).sort({ date: -1 });
    res.status(200).json(transactions);
  } catch (error: any) {
    res.status(500).json({ message: 'Server error', error: error.message });
  }
};

export const getTransactionById = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const transaction = await Transaction.findOne({ _id: req.params.id, userId: req.user?.id });
    
    if (!transaction) {
      res.status(404).json({ message: 'Transaction not found' });
      return;
    }

    res.status(200).json(transaction);
  } catch (error: any) {
    res.status(500).json({ message: 'Server error', error: error.message });
  }
};

export const updateTransaction = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const parsedData = transactionSchema.partial().parse(req.body);

    const transaction = await Transaction.findOneAndUpdate(
      { _id: req.params.id, userId: req.user?.id },
      { $set: parsedData },
      { new: true }
    );

    if (!transaction) {
      res.status(404).json({ message: 'Transaction not found' });
      return;
    }

    res.status(200).json(transaction);
  } catch (error: any) {
    res.status(400).json({ message: 'Validation error or server error', error: error.message });
  }
};

export const deleteTransaction = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const transaction = await Transaction.findOneAndDelete({ _id: req.params.id, userId: req.user?.id });

    if (!transaction) {
      res.status(404).json({ message: 'Transaction not found' });
      return;
    }

    res.status(200).json({ message: 'Transaction deleted successfully' });
  } catch (error: any) {
    res.status(500).json({ message: 'Server error', error: error.message });
  }
};

import type { Request, Response } from 'express';
import User from '../models/user.model.js';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { registerUserSchema, loginUserSchema } from '../validators/user.validator.js';
import type { AuthRequest } from '../middleware/authmiddleware.js';

export const registerUser = async (req: Request, res: Response): Promise<void> => {
  console.log("register user controller hit ");
  try {
    const parsedData = registerUserSchema.parse(req.body);

    const existingUser = await User.findOne({
      $or: [{ email: parsedData.email }, { username: parsedData.username }]
    });

    if (existingUser) {
      res.status(400).json({ message: 'User with this email or username already exists' });
      return;
    }

    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(parsedData.password, salt);

    const newUser = new User({
      username: parsedData.username,
      email: parsedData.email,
      password: hashedPassword
    });

    await newUser.save();

    const token = jwt.sign(
      { id: newUser._id, email: newUser.email },
      process.env.JWT_SECRET || 'secret',
      { expiresIn: '1d' }
    );

    res.status(201).json({
      token,
      user: { id: newUser._id, username: newUser.username, email: newUser.email },
      message: 'User registered successfully'
    });
  } catch (error: any) {
    res.status(400).json({ message: 'Validation error or server error', error: error.message });
  }
};

export const loginUser = async (req: Request, res: Response): Promise<void> => {
  console.log("login user controller hit ");
  try {
    const parsedData = loginUserSchema.parse(req.body);

    const user = await User.findOne({ email: parsedData.email });
    if (!user) {
      res.status(400).json({ message: 'Invalid credentials' });
      return;
    }

    const isMatch = await bcrypt.compare(parsedData.password, user.password);
    if (!isMatch) {
      res.status(400).json({ message: 'Invalid credentials' });
      return;
    }

    const token = jwt.sign(
      { id: user._id, email: user.email },
      process.env.JWT_SECRET || 'secret',
      { expiresIn: '1d' }
    );

    res.status(200).json({ token, user: { id: user._id, username: user.username, email: user.email } });
  } catch (error: any) {
    res.status(400).json({ message: 'Validation error or server error', error: error.message });
  }
};

export const getProfile = async (req: AuthRequest, res: Response): Promise<void> => {
  console.log("get profile controller hit");
  try {
    if (!req.user) {
      res.status(401).json({ message: 'Unauthorized' });
      return;
    }

    const user = await User.findById(req.user.id).select('-password');
    if (!user) {
      res.status(404).json({ message: 'User not found' });
      return;
    }

    res.status(200).json(user);
  } catch (error: any) {
    res.status(500).json({ message: 'Server error', error: error.message });
  }
};

