.landing-container {
  min-height: 100vh;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  overflow-x: hidden;
}

.text-blue {
  color: var(--accent-blue);
}

.ml-2 {
  margin-left: 0.5rem;
}

/* Nav */
.landing-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  z-index: 100;
  border-bottom: 1px solid var(--border-color);
}

.landing-nav-content {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.landing-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: -0.025em;
  transition: transform var(--transition-fast);
}

.landing-brand:hover {
  transform: scale(1.02);
}

.landing-nav-actions {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.nav-login-link {
  font-weight: 500;
  color: var(--text-secondary);
  padding: 0.5rem 1rem;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-login-link:hover {
  color: var(--text-primary);
  background-color: var(--bg-secondary);
}

/* Hero Section */
.hero-section {
  padding: 8rem 1.5rem 4rem;
  text-align: center;
  background: radial-gradient(circle at 50% -20%, var(--accent-blue-light) 0%, var(--bg-primary) 50%);
}

.hero-content {
  max-width: 900px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 1rem 0.375rem 0.375rem;
  background-color: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 2rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.badge-pill:hover {
  background-color: var(--accent-blue-light);
  border-color: var(--accent-blue);
}

.badge-new {
  background-color: var(--accent-blue);
  color: white;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.hero-title {
  font-size: 3.5rem;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.04em;
  margin-bottom: 1.5rem;
  max-width: 900px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  margin-bottom: 2.5rem;
  max-width: 650px;
  line-height: 1.7;
}

.hero-actions {
  margin-bottom: 4rem;
}

.hero-btn {
  padding: 1rem 2.5rem;
  font-size: 1.125rem;
  box-shadow: 0 4px 14px 0 rgba(37, 99, 235, 0.39);
}

/* Abstract Mockup */
.hero-image-container {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
  perspective: 1000px;
}

.hero-mockup {
  background-color: white;
  border-radius: 12px;
  border: 1px solid var(--border-color);
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.15);
  overflow: hidden;
  height: 400px;
  display: flex;
  flex-direction: column;
  transform: rotateX(5deg);
  transform-origin: top;
  transition: transform var(--transition-slow);
}

.hero-mockup:hover {
  transform: rotateX(0deg);
}

.mockup-header {
  height: 40px;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-secondary);
  display: flex;
  align-items: center;
  padding: 0 1rem;
}

.mockup-dots {
  display: flex;
  gap: 6px;
}

.mockup-dots span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: #e2e8f0;
  transition: all var(--transition-fast);
}

.mockup-body {
  flex: 1;
  display: flex;
}

.mockup-sidebar {
  width: 60px;
  border-right: 1px solid var(--border-color);
  background-color: var(--bg-tertiary);
}

.mockup-content {
  flex: 1;
  padding: 2rem;
  background-color: var(--bg-secondary);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mockup-cards-row {
  display: flex;
  gap: 1rem;
}

.mockup-card-small {
  flex: 1;
  height: 80px;
  background-color: white;
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

.mockup-chart {
  flex: 1;
  background-color: white;
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

/* Common Section Styles */
.section-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5rem 1.5rem;
}

.section-header {
  text-align: center;
  margin-bottom: 4rem;
}

.section-header h2 {
  font-size: 2.25rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  margin-bottom: 1rem;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--text-secondary);
}

/* Features Grid */
.features-section {
  background-color: var(--bg-secondary);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 2rem;
}

.feature-card {
  background-color: white;
  padding: 2.5rem 2rem;
  border-radius: 1rem;
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.feature-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-md);
}

.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background-color: var(--accent-blue-light);
  color: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  transition: transform var(--transition-fast);
}

.feature-card:hover .feature-icon {
  transform: scale(1.1);
}

.feature-card h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
}

.feature-card p {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* Steps */
.steps-container {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 2rem;
  position: relative;
}

.step-item {
  flex: 1;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  z-index: 2;
}

.step-number {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-hover));
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
}

.step-icon {
  color: var(--accent-blue);
  margin-bottom: 1.5rem;
  padding: 1.5rem;
  background-color: var(--accent-blue-light);
  border-radius: 50%;
  transition: all var(--transition-base);
}

.step-item:hover .step-icon {
  background-color: var(--bg-tertiary);
  transform: scale(1.1);
}

.step-item h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
}

.step-item p {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

.step-connector {
  flex: 0.2;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--border-color), transparent);
  margin-top: 16px;
}

/* CTA */
.cta-section {
  padding: 6rem 1.5rem;
  text-align: center;
  background: linear-gradient(135deg, var(--text-primary) 0%, rgba(15, 23, 42, 0.95) 100%);
  color: white;
}

.cta-container {
  max-width: 600px;
  margin: 0 auto;
}

.cta-container h2 {
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  margin-bottom: 1.5rem;
}

.cta-container p {
  font-size: 1.125rem;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.cta-btn {
  background-color: white;
  color: var(--text-primary);
  transition: all var(--transition-base);
}

.cta-btn:hover {
  background-color: var(--bg-secondary);
  transform: translateY(-2px);
}

/* Footer */
.footer {
  border-top: 1px solid var(--border-color);
  padding: 3rem 1.5rem;
  background-color: white;
}

.footer-content {
  max-width: 1200px;
