.profile-page {
  min-height: 100vh;
  background-color: var(--bg-secondary);
}

.profile-main {
  max-width: 600px;
  margin: 0 auto;
  padding: 2.5rem 1.5rem;
  display: flex;
  justify-content: center;
}

.profile-card {
  width: 100%;
}

.profile-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 3rem 2.5rem;
}

.profile-avatar-large {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue-light) 0%, #dbeafe 100%);
  color: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 3rem;
  margin-bottom: 1.75rem;
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.15);
  transition: transform var(--transition-base);
}

.profile-avatar-large:hover {
  transform: scale(1.05);
}

.profile-name {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
  text-align: center;
}

.profile-role {
  display: inline-flex;
  align-items: center;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--accent-blue);
  background-color: var(--accent-blue-light);
  padding: 0.375rem 0.875rem;
  border-radius: 9999px;
  margin-bottom: 2.5rem;
}

.profile-details {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 3rem;
}

.detail-item {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  padding: 1.25rem 0;
  border-bottom: 1px solid var(--border-color);
  transition: background-color var(--transition-fast);
}

.detail-item:last-child {
  border-bottom: none;
}

.detail-item:hover {
  background-color: rgba(255, 255, 255, 0.5);
}

.detail-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background-color: var(--accent-blue-light);
  color: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.detail-info {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
}

.detail-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.375rem;
}

.detail-value {
  font-size: 1rem;
  color: var(--text-primary);
  font-weight: 500;
  word-break: break-word;
}

.profile-actions {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.full-width-link {
  width: 100%;
  display: block;
}

.logout-btn {
  background-color: var(--danger-bg);
  color: var(--danger);
  transition: all var(--transition-base);
}

.logout-btn:hover {
  background-color: #fecaca;
  color: #dc2626;
}

.mr-1 { margin-right: 0.25rem; }
.mr-2 { margin-right: 0.5rem; }

/* Responsive */
@media (max-width: 768px) {
